// ============================================================
// Rule: THM_Unsigned sensapi.dll Sideloaded via usysdiag.exe
// Vendor: Windows
// Objective:
// Detect activity associated with THM_Unsigned sensapi.dll Sideloaded via usysdiag.exe.
// Severity: SEV_040_HIGH
// Category: EXECUTION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0003 - Persistence
// Technique: T1574.002 - Hijack Execution Flow: DLL Side-Loading
// Tactic: TA0005 - Defense Evasion
// Technique: T1574.002 - Hijack Execution Flow: DLL Side-Loading
// Tactic: TA0004 - Privilege Escalation
// Technique: T1574.002 - Hijack Execution Flow: DLL Side-Loading

// Desabilita diferenciação entre maiúsculas e minúsculas para comparações
config case_sensitive = false  

// Define o dataset de origem como dados brutos do Cortex
| dataset = xdr_data  

// Filtra apenas eventos relacionados a carregamento de módulos/bibliotecas (DLLs)
| filter event_type = ENUM.LOAD_IMAGE  

// Restringe para processos "usysdiag.exe"
// Possível binário abusado ou renomeado por malware
| filter actor_process_image_name = "usysdiag.exe"  

// Busca carregamento específico da biblioteca sensapi.dll
| filter action_module_path contains "sensapi.dll"  

// Foca em módulos não assinados digitalmente (indicador de potencial)
| filter action_module_signature_status = ENUM.UNSIGNED  

// Seleciona os campos relevantes para análise
| fields agent_hostname,                     // Host onde ocorreu o evento
         actor_process_image_name,           // Nome do processo responsável
         actor_process_image_path,           // Caminho completo do executável
         action_module_path,                 // Caminho da DLL carregada
         action_module_signature_status,     // Status da assinatura digital do módulo
         action_module_sha256                // Hash SHA256 da DLL
